/**
 * The site registry: keyword map (generated by clustering) + written content + publish rules, in one place.
 * A page is published only if: its registry row is status `launch` and `adsense: green` (docs/10 §10), its content
 * exists and validates, its batch ≤ CURRENT_BATCH, and (for instances) its parent tool is published and its family
 * builds it (the demand gate, docs/10 §5).
 */
import keywordMap from './keyword-map.json';
import { TOOL_CONTENT } from './calculators';
import { ToolSchema, type Tool } from './schema';
import { CATEGORIES, categoryBySlug, type Category } from './taxonomy';
import { buildInstance } from '@/lib/families';
import type { InstancePage } from '@/lib/families/types';

export interface RegistryRow {
  url: string;
  type: 'calculator' | 'guide' | 'instance';
  category: string;
  subcategory: string | null;
  name: string;
  primary: string;
  secondary: string[];
  faqCandidates: string[];
  parent: string | null;
  family: string | null;
  wave: number;
  status: 'launch' | 'queue' | 'later-kd' | 'skip-vendor-serp' | 'ymyl-later' | 'not-green';
  adsense: 'green' | 'not-green';
  reason?: string;
  evidence: { primaryVolume: number | null; primaryKd: number | null; clusterVolume: number; keywords: number };
}

export const REGISTRY: readonly RegistryRow[] = keywordMap as RegistryRow[];
const rowByUrl = new Map(REGISTRY.map((r) => [r.url, r]));
export const registryRow = (url: string): RegistryRow | undefined => rowByUrl.get(url);
export const isPublishableRow = (r: RegistryRow | undefined): r is RegistryRow => !!r && r.status === 'launch' && r.adsense === 'green';

/** 1 = launch batch A only, 2 = batches A + B (docs/07). Production sets this explicitly per publishing batch. */
export const CURRENT_BATCH = Number(process.env.NEXT_PUBLIC_CURRENT_BATCH ?? '2');

/** Build date (UTC). Date-dependent pages are rebuilt daily (docs/10 §5). */
export const BUILD_TODAY = new Date().toISOString().slice(0, 10);

export const ALL_TOOLS: readonly Tool[] = TOOL_CONTENT.map((t) => ToolSchema.parse(t));

export interface PublishedTool extends Tool {
  category: Category;
  subcategory: string;
  row: RegistryRow;
}

export const publishedTools: readonly PublishedTool[] = ALL_TOOLS.flatMap((t) => {
  const row = rowByUrl.get(t.url);
  const category = row && categoryBySlug(row.category);
  if (!isPublishableRow(row) || row.type !== 'calculator' || !category || t.batch > CURRENT_BATCH) return [];
  return [{ ...t, category, subcategory: row.subcategory ?? 'Other', row }];
});
const toolByUrl = new Map(publishedTools.map((t) => [t.url, t]));
export const publishedTool = (url: string): PublishedTool | undefined => toolByUrl.get(url);

export interface PublishedInstance extends InstancePage {
  url: string;
  parent: PublishedTool;
  row: RegistryRow;
}

export const publishedInstances: readonly PublishedInstance[] = REGISTRY.flatMap((row) => {
  if (row.type !== 'instance' || !isPublishableRow(row) || !row.parent || !row.family) return [];
  const parent = toolByUrl.get(row.parent);
  if (!parent) return [];
  const slug = row.url.slice(row.parent.length).replace(/\/$/, '');
  const page = buildInstance(row.family, slug, BUILD_TODAY);
  return page ? [{ ...page, url: row.url, parent, row }] : [];
});

/** Categories with at least one published tool (playbook §0.2b: no empty hubs), in taxonomy order. */
export const publishedCategories: readonly Category[] = CATEGORIES.filter((c) => publishedTools.some((t) => t.category.slug === c.slug));

export const categoryPath = (c: Pick<Category, 'slug'>): string => `/${c.slug}/`;

/** Popularity = researched demand (cluster volume, plus instance demand for programmatic parents). */
export const demand = (t: PublishedTool): number =>
  t.row.evidence.clusterVolume + publishedInstances.filter((i) => i.parent.url === t.url).reduce((s, i) => s + (i.row.evidence.primaryVolume ?? 0), 0);

/** Trust pages, linked from every page's footer. */
export const TRUST_PAGES = [
  { path: '/about/', name: 'About' },
  { path: '/methodology/', name: 'Methodology' },
  { path: '/editorial-policy/', name: 'Editorial policy' },
  { path: '/privacy/', name: 'Privacy' },
  { path: '/disclosure/', name: 'Disclosure' },
  { path: '/contact/', name: 'Contact' },
] as const;

export const AUTHOR = { slug: 'ahsan-khan', path: '/authors/ahsan-khan/' } as const;

/**
 * Category <title> and meta description that never promise tools that aren't live (also used by llms.txt).
 * The curated copy in taxonomy.ts describes the whole planned category (e.g. "LCM, volume and right triangles"), so
 * it's used only once every planned calculator in that category is published. Until then both are generated from
 * the published tools, which keeps them accurate as the site grows.
 */
/** True once every planned (green, non-skipped) calculator in the category is published. */
export function categoryComplete(c: Category): boolean {
  const planned = REGISTRY.filter((r) => r.type === 'calculator' && r.category === c.slug && r.status !== 'skip-vendor-serp' && r.adsense === 'green');
  return planned.every((r) => publishedTools.some((t) => t.url === r.url));
}

/** The category page's opening paragraph: the full curated intro once complete, otherwise the live-tools intro. */
export const categoryIntro = (c: Category): string => (categoryComplete(c) ? c.intro : (c.introLive ?? c.intro));

export function categoryMeta(c: Category): { title: string; description: string } {
  const live = publishedTools.filter((t) => t.category.slug === c.slug).sort((a, b) => demand(b) - demand(a));
  if (categoryComplete(c)) return { title: c.title, description: c.description };
  const head = c.title.split(':')[0]!.trim(); // "Math Calculators"
  const list = (names: string[]) => (names.length < 2 ? names.join('') : `${names.slice(0, -1).join(', ')} and ${names.at(-1)}`);
  let names = live.map((t) => t.name);
  let description = `Free ${head.toLowerCase()} that show the formula and a worked example: ${list(names)}.`;
  while (description.length > 155 && names.length > 1) {
    names = names.slice(0, -1);
    description = `Free ${head.toLowerCase()} that show the formula and a worked example, including the ${list(names)}.`;
  }
  return { title: `${head} With Formulas and Steps`, description };
}
